function BatchSampler(j, d) // シードjで疑似乱数生成器を初期化します。 Rand_Init(j) // 0からK - 1までの相異なるd個の整数をサンプリングします。 for k = 0, ..., d - 1 do r = Rand() % K while r already exists in idx do r = Rand() % K idx[k] = r
// d x Mの行列をサンプリングします for r = 0, ..., d - 1 do for c = 0, ..., M - 1 do G[r, c] = Rand() % 256
return idx, G
